[metadata] {"type": "create", "filePath": "/app/output/ocean_health.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Ocean Health Multi-Indicator Time Series (1990–2024)</title>
<link href="https://fonts.googleapis.com/css2?family=IBM+Plex+Sans:wght@300;400;500;600;700&family=IBM+Plex+Mono:wght@400;500&display=swap" rel="stylesheet">
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
<style>
  :root {
    --bg: #f5f3ef;
    --surface: #ffffff;
    --surface-alt: #edeae4;
    --border: rgba(0,0,0,0.10);
    --text: #1a1a1a;
    --text-dim: #5a5a5a;
    --text-muted: #8a8a8a;

    /* Four indicator colors — teal, amber, rose, slate */
    --c-temp: #0369a1;       /* SST anomaly — deep teal/blue */
    --c-temp-bg: rgba(3,105,161,0.12);
    --c-ph: #7c5e1e;         /* Ocean pH — warm amber-brown */
    --c-ph-bg: rgba(124,94,30,0.12);
    --c-coral: #b91c1c;      /* Coral cover — deep rose/red */
    --c-coral-bg: rgba(185,28,28,0.12);
    --c-plastic: #1e5631;    /* Plastic — forest green */
    --c-plastic-bg: rgba(30,86,49,0.12);

    --font-body: 'IBM Plex Sans', system-ui, sans-serif;
    --font-mono: 'IBM Plex Mono', monospace;
  }

  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

  body {
    font-family: var(--font-body);
    background: var(--bg);
    color: var(--text);
    min-height: 100vh;
    padding: 32px 40px 48px;
  }

  /* Subtle grid background */
  body::before {
    content: '';
    position: fixed;
    inset: 0;
    background-image:
      linear-gradient(to right, rgba(0,0,0,0.035) 1px, transparent 1px),
      linear-gradient(to bottom, rgba(0,0,0,0.035) 1px, transparent 1px);
    background-size: 40px 40px;
    pointer-events: none;
    z-index: 0;
  }

  .page-wrap { position: relative; z-index: 1; max-width: 1100px; margin: 0 auto; }

  /* Header */
  .header {
    margin-bottom: 28px;
    border-bottom: 2px solid var(--border);
    padding-bottom: 20px;
  }

  .header-eyebrow {
    font-family: var(--font-mono);
    font-size: 10px;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: var(--text-muted);
    margin-bottom: 8px;
  }

  .header-title {
    font-size: 22px;
    font-weight: 700;
    letter-spacing: -0.01em;
    color: var(--text);
    line-height: 1.2;
    margin-bottom: 6px;
  }

  .header-subtitle {
    font-size: 13px;
    color: var(--text-dim);
    font-weight: 400;
    line-height: 1.5;
    max-width: 680px;
  }

  /* KPI strip */
  .kpi-strip {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 12px;
    margin-bottom: 20px;
  }

  .kpi-card {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 4px;
    padding: 14px 16px;
    position: relative;
    overflow: hidden;
  }

  .kpi-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 3px;
  }

  .kpi-card.temp::before  { background: var(--c-temp); }
  .kpi-card.ph::before    { background: var(--c-ph); }
  .kpi-card.coral::before { background: var(--c-coral); }
  .kpi-card.plastic::before { background: var(--c-plastic); }

  .kpi-label {
    font-family: var(--font-mono);
    font-size: 9.5px;
    letter-spacing: 0.09em;
    text-transform: uppercase;
    color: var(--text-muted);
    margin-bottom: 6px;
  }

  .kpi-value {
    font-size: 24px;
    font-weight: 700;
    letter-spacing: -0.02em;
    line-height: 1;
    margin-bottom: 4px;
  }

  .kpi-card.temp   .kpi-value { color: var(--c-temp); }
  .kpi-card.ph     .kpi-value { color: var(--c-ph); }
  .kpi-card.coral  .kpi-value { color: var(--c-coral); }
  .kpi-card.plastic .kpi-value { color: var(--c-plastic); }

  .kpi-change {
    font-size: 11px;
    color: var(--text-dim);
    font-weight: 500;
  }

  .kpi-change .arrow { margin-right: 2px; }
  .kpi-change.bad  { color: #b91c1c; }
  .kpi-change.warn { color: #92400e; }

  /* Main chart card */
  .chart-card {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 4px;
    padding: 28px 28px 20px;
    margin-bottom: 16px;
    box-shadow: 0 2px 12px rgba(0,0,0,0.055);
  }

  .chart-title-row {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    margin-bottom: 20px;
    gap: 16px;
  }

  .chart-title {
    font-size: 14px;
    font-weight: 600;
    color: var(--text);
    letter-spacing: -0.01em;
  }

  .chart-period {
    font-family: var(--font-mono);
    font-size: 11px;
    color: var(--text-muted);
    background: var(--surface-alt);
    border: 1px solid var(--border);
    border-radius: 3px;
    padding: 3px 8px;
    white-space: nowrap;
    flex-shrink: 0;
  }

  /* Legend */
  .legend {
    display: flex;
    flex-wrap: wrap;
    gap: 8px 20px;
    margin-bottom: 18px;
  }

  .legend-item {
    display: flex;
    align-items: center;
    gap: 7px;
    font-size: 11.5px;
    color: var(--text-dim);
  }

  .legend-line {
    width: 24px;
    height: 2px;
    border-radius: 1px;
    flex-shrink: 0;
  }

  .legend-line.dashed {
    background: repeating-linear-gradient(90deg, currentColor 0 5px, transparent 5px 9px);
    height: 0;
    border-top: 2px dashed;
  }

  .legend-line.dotted {
    background: repeating-linear-gradient(90deg, currentColor 0 3px, transparent 3px 7px);
    height: 0;
    border-top: 2px dotted;
  }

  .legend-unit {
    font-family: var(--font-mono);
    font-size: 9.5px;
    color: var(--text-muted);
    margin-left: 1px;
  }

  /* Chart container */
  .chart-wrap {
    position: relative;
    width: 100%;
    height: 420px;
  }

  /* Annotation stripe */
  .annotation-strip {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 10px;
    margin-top: 4px;
  }

  .annotation {
    background: var(--surface-alt);
    border-left: 3px solid var(--border);
    border-radius: 0 3px 3px 0;
    padding: 9px 12px;
    font-size: 11.5px;
    color: var(--text-dim);
    line-height: 1.5;
  }

  .annotation.accent-temp   { border-color: var(--c-temp); }
  .annotation.accent-coral  { border-color: var(--c-coral); }
  .annotation.accent-ph     { border-color: var(--c-ph); }
  .annotation.accent-plastic{ border-color: var(--c-plastic); }

  .annotation strong { color: var(--text); font-weight: 600; }

  /* Footer */
  .footer {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    gap: 16px;
    padding-top: 16px;
    border-top: 1px solid var(--border);
    margin-top: 20px;
  }

  .footer-note {
    font-size: 10.5px;
    color: var(--text-muted);
    line-height: 1.6;
    max-width: 680px;
  }

  .footer-note code {
    font-family: var(--font-mono);
    font-size: 9.5px;
    background: var(--surface-alt);
    padding: 1px 4px;
    border-radius: 2px;
  }

  .footer-date {
    font-family: var(--font-mono);
    font-size: 10px;
    color: var(--text-muted);
    white-space: nowrap;
    text-align: right;
    flex-shrink: 0;
  }

  /* Axis labels positioned in canvas area — handled via Chart.js plugins */
</style>
</head>
