        <span>Coral Cover</span>
        <span class="legend-unit">(%, right axis 2)</span>
      </div>
      <div class="legend-item">
        <div class="legend-line" style="background: repeating-linear-gradient(90deg,#1e5631 0 4px,transparent 4px 8px); height:2.5px;"></div>
        <span>Ocean Plastic</span>
