const puppeteer = require('/tmp/node_modules/puppeteer');
const path = require('path');

(async () => {
  const browser = await puppeteer.launch({
    args: ['--no-sandbox', '--disable-setuid-sandbox', '--disable-dev-shm-usage'],
    headless: 'new'
  });
  const page = await browser.newPage();

  // Set viewport for a publication-quality image
  await page.setViewport({ width: 1200, height: 900, deviceScaleFactor: 2 });

  const filePath = path.resolve('/app/output/ocean_health.html');
  await page.goto(`file://${filePath}`, { waitUntil: 'networkidle0', timeout: 30000 });

  // Wait for Chart.js to finish rendering
  await page.waitForTimeout(2500);

  // Get the full page height
  const bodyHeight = await page.evaluate(() => document.body.scrollHeight);
  await page.setViewport({ width: 1200, height: bodyHeight, deviceScaleFactor: 2 });
  await page.waitForTimeout(500);

  await page.screenshot({
    path: '/app/output/result.png',
    fullPage: true,
    type: 'png'
  });

  await browser.close();
  console.log('Done: /app/output/result.png');
})();

