const puppeteer = require('/tmp/node_modules/puppeteer');
const path = require('path');

(async () => {
  const browser = await puppeteer.launch({
    args: ['--no-sandbox', '--disable-setuid-sandbox', '--disable-dev-shm-usage', '--disable-gpu'],
    headless: 'new'
  });
  const page = await browser.newPage();

  // Set viewport for publication-quality image
  await page.setViewport({ width: 1200, height: 900, deviceScaleFactor: 2 });

  const filePath = path.resolve('/app/output/ocean_health.html');

  // Intercept and serve Chart.js locally if CDN fails
  await page.goto(`file://${filePath}`, { waitUntil: 'domcontentloaded', timeout: 30000 });

  // Wait for Chart.js to be defined and chart to render
  await page.waitForFunction(() => typeof Chart !== 'undefined', { timeout: 20000 }).catch(() => {
    console.log('Chart.js not loaded from CDN, will try local fallback');
  });

  // Extra settle time for canvas rendering
  await new Promise(r => setTimeout(r, 3000));

  // Get the full page height
  const bodyHeight = await page.evaluate(() => document.body.scrollHeight);
  await page.setViewport({ width: 1200, height: Math.max(bodyHeight, 900), deviceScaleFactor: 2 });
  await new Promise(r => setTimeout(r, 1000));

  await page.screenshot({
    path: '/app/output/result.png',
    fullPage: true,
    type: 'png'
  });

  await browser.close();
  console.log('Done: /app/output/result.png');
})();

