const puppeteer = require('/tmp/node_modules/puppeteer');
const path = require('path');
const fs = require('fs');

(async () => {
  const browser = await puppeteer.launch({
    args: ['--no-sandbox', '--disable-setuid-sandbox', '--disable-dev-shm-usage', '--disable-gpu'],
    headless: 'new'
  });
  const page = await browser.newPage();

  await page.setViewport({ width: 1200, height: 900, deviceScaleFactor: 2 });

  // Read Chart.js content and HTML
  const chartJs = fs.readFileSync('/tmp/node_modules/chart.js/dist/chart.umd.min.js', 'utf8');
  let html = fs.readFileSync('/app/output/ocean_health.html', 'utf8');

  // Replace CDN script tag with inline Chart.js
  html = html.replace(
    '<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>',
    `<script>${chartJs}</script>`
  );

  await page.setContent(html, { waitUntil: 'domcontentloaded', timeout: 30000 });

  // Wait for Chart.js to be defined
  await page.waitForFunction(() => typeof Chart !== 'undefined', { timeout: 10000 });

  // Let canvas settle
  await new Promise(r => setTimeout(r, 2000));

  const bodyHeight = await page.evaluate(() => document.body.scrollHeight);
  await page.setViewport({ width: 1200, height: Math.max(bodyHeight, 900), deviceScaleFactor: 2 });
  await new Promise(r => setTimeout(r, 800));

  await page.screenshot({
    path: '/app/output/result.png',
    fullPage: true,
    type: 'png'
  });

  await browser.close();
  console.log('Done: /app/output/result.png');
})();

