const puppeteer = require('/tmp/node_modules/puppeteer');
const fs = require('fs');

(async () => {
  const browser = await puppeteer.launch({
    args: ['--no-sandbox', '--disable-setuid-sandbox', '--disable-dev-shm-usage', '--disable-gpu'],
    headless: 'new'
  });
  const page = await browser.newPage();

  page.on('console', msg => console.log('PAGE LOG:', msg.text()));
  page.on('pageerror', err => console.log('PAGE ERR:', err));

  await page.setViewport({ width: 1200, height: 900, deviceScaleFactor: 2 });

  const chartJs = fs.readFileSync('/tmp/node_modules/chart.js/dist/chart.umd.min.js', 'utf8');
  let html = fs.readFileSync('/app/output/ocean_health.html', 'utf8');
  html = html.replace(
    '<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>',
    `<script>${chartJs}</script>`
  );

  await page.setContent(html, { waitUntil: 'domcontentloaded', timeout: 30000 });
  await page.waitForFunction(() => typeof Chart !== 'undefined', { timeout: 10000 });
  await new Promise(r => setTimeout(r, 3000));

  // Inspect canvas
  const info = await page.evaluate(() => {
    const canvas = document.getElementById('mainChart');
    if (!canvas) return { error: 'no canvas' };
    const ctx = canvas.getContext('2d');
    return {
      width: canvas.width,
      height: canvas.height,
      parent: canvas.parentElement ? canvas.parentElement.className : 'none',
      chartDefined: typeof Chart !== 'undefined',
      chartVersion: typeof Chart !== 'undefined' ? Chart.version : null
    };
  });
  console.log('Canvas info:', JSON.stringify(info));

  await browser.close();
})();

